1	import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";
2	
3	async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
4	  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
5	  return (await (result as any).json()) as T[];
6	}
7	
8	export async function metrics_match_source(ctx: AssertionContext): Promise<AssertionResult> {
9	  const sourceRows = await queryRows<{ total: number; users: number; revenue: number }>(
10	    ctx,
11	    "SELECT count() AS total, uniq(user_id) AS users, sum(revenue) AS revenue FROM analytics.events",
12	  );
13	  const src = sourceRows[0];
14	  const apiRes = await fetch("http://localhost:3000/api/metrics");
15	  if (!apiRes.ok) {
16	    return { passed: false, message: "API metrics failed.", details: { status: apiRes.status } };
17	  }
18	  const data = (await apiRes.json()) as { total_events?: number; unique_users?: number; total_revenue?: number };
19	  const apiTotal = Number(data.total_events ?? data.total ?? 0);
20	  const apiUsers = Number(data.unique_users ?? data.users ?? 0);
21	  const apiRevenue = Number(data.total_revenue ?? data.revenue ?? 0);
22	  const totalMatch = Math.abs(apiTotal - Number(src?.total ?? 0)) < 10;
23	  const usersMatch = Math.abs(apiUsers - Number(src?.users ?? 0)) < 10;
24	  const revenueMatch = Math.abs(apiRevenue - Number(src?.revenue ?? 0)) < 100;
25	  const passed = totalMatch && usersMatch && revenueMatch;
26	  return {
27	    passed,
28	    message: passed ? "Metrics match source." : "API metrics do not match source aggregates.",
29	    details: { apiTotal, apiUsers, apiRevenue, srcTotal: src?.total, srcUsers: src?.users, srcRevenue: src?.revenue },
30	  };
31	}
